import sys
from pptx import Presentation

p = Presentation(sys.argv[1])
print('slides:', len(p.slides), 'size:', p.slide_width, p.slide_height)
for i, s in enumerate(p.slides, 1):
    print('--- slide', i, 'layout:', s.slide_layout.name)
    for sh in s.shapes:
        t = ''
        if sh.has_text_frame:
            t = sh.text_frame.text.replace('\n', ' | ')
        print('   ', sh.shape_type, '|', sh.name, '|', repr(t)[:200])
    if s.has_notes_slide:
        print('    NOTES:', repr(s.notes_slide.notes_text_frame.text))
